// Relevant snippet - Source metadata structure
export interface SourceDocument {
  id: string;
  title: string;
  content: string;
  chunkId: string;
  metadata: Record<string, unknown>;
  embedding?: number[];
  createdAt: number;
  updatedAt: number;
}

export interface SearchResult {
  id: string;
  score: number;
  document: SourceDocument;
}

// Relevant snippet - RAG store pattern
import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import Dexie from 'dexie';

interface RAGState {
  searchResults: SearchResult[];
  sources: SourceDocument[];
  isSearching: boolean;
  lastSearchQuery: string;
}

// Existing CitationSidebar component structure
interface Citation {
  id: string;
  sourceId: string;
  sourceTitle: string;
  relevanceScore: number;
  excerpt: string;
}

export const CitationSidebar: React.FC<{ citations: Citation[] }> = ({ citations }) => {
  return (
    <div className="citation-sidebar">
      {citations.map(citation => (
        <CitationCard key={citation.id} citation={citation} />
      ))}
    </div>
  );
};
